<script lang="ts">
  import { CONSTANTS } from 'src/constants';
  import { FoundryAdapter } from 'src/foundry/foundry-adapter';
  import { settings } from 'src/settings/settings.svelte';
  import { getSheetContext } from 'src/sheets/sheet-context.svelte';
  import type { ActorSheetContextV1 } from 'src/types/types';
  import { ActiveEffectsHelper } from 'src/utils/active-effect';

  interface Props {
    tools?: [key: string, value: any][];
  }

  let { tools = [] }: Props = $props();

  let context = $derived(getSheetContext<ActorSheetContextV1>());

  const localize = FoundryAdapter.localize;

  /**
   * Resolves a tool's base item UUID for reference tooltips.
   * `Trait.getBaseItemUUID` is probed because it is absent on older dnd5e;
   * a config `id` that already looks like a UUID is used directly.
   */
  function getToolReference(key: string): string | undefined {
    const id = CONFIG.DND5E.tools?.[key]?.id;
    if (!id) {
      return undefined;
    }

    if (typeof dnd5e.documents.Trait?.getBaseItemUUID === 'function') {
      return dnd5e.documents.Trait.getBaseItemUUID(id);
    }

    return id.includes('.') ? id : undefined;
  }
</script>

<ul
  class="trait-list tools"
  data-tidy-sheet-part={CONSTANTS.SHEET_PARTS.TOOLS_LIST}
>
  {#each tools as [key, tool]}
    {@const reference = settings.value.referenceTooltipTool
      ? getToolReference(key)
      : undefined}
    <li
      class="tool"
      data-tidy-sheet-part={CONSTANTS.SHEET_PARTS.TOOL_CONTAINER}
      data-key={key}
      data-reference-tooltip={reference ?? null}
      data-tooltip-direction="RIGHT"
    >
      {#if context.editable && !context.lockSensitiveFields}
        {@const activeEffectApplied =
          ActiveEffectsHelper.isActiveEffectAppliedToField(
            context.actor,
            `system.tools.${key}.value`,
          )}
        <button
          type="button"
          class="tool-proficiency-toggle inline-transparent-button"
          title={tool.hover}
          onclick={(event) => {
            event.preventDefault();
            event.stopPropagation();
            FoundryAdapter.cycleProficiency(
              context.actor,
              key,
              tool.value,
              'tools',
            );
          }}
          oncontextmenu={(event) => {
            event.preventDefault();
            event.stopPropagation();
            FoundryAdapter.cycleProficiency(
              context.actor,
              key,
              tool.value,
              'tools',
              true,
            );
          }}
          data-tidy-sheet-part={CONSTANTS.SHEET_PARTS.TOOL_PROFICIENCY_TOGGLE}
          tabindex={settings.value.useAccessibleKeyboardSupport ? 0 : -1}
          disabled={activeEffectApplied}
          data-tooltip={activeEffectApplied
            ? localize('DND5E.ActiveEffectOverrideWarning')
            : null}
        >
          {@html tool.icon}
        </button>
      {:else}
        <span title={tool.hover} class="tool-proficiency-readonly"
          >{@html tool.icon}</span
        >
      {/if}

      {#if context.editable}
        <button
          type="button"
          class="tool-check-roller inline-transparent-button rollable"
          onclick={(event) => context.actor.rollToolCheck({ tool: key, event })}
          data-tidy-sheet-part={CONSTANTS.SHEET_PARTS.TOOL_ROLLER}
          tabindex={settings.value.useAccessibleKeyboardSupport ? 0 : -1}
        >
          {tool.label}
        </button>
      {:else}
        <span class="tool-check-roller">
          {tool.label}
        </span>
      {/if}

      {#if context.unlocked}
        <button
          type="button"
          class="tool-proficiency-editor inline-icon-button"
          title={localize('DND5E.ToolConfigure')}
          onclick={(event) => {
            event.preventDefault();
            event.stopPropagation();
            FoundryAdapter.renderSkillToolConfig(context.actor, 'tool', key);
          }}
          data-tidy-sheet-part={CONSTANTS.SHEET_PARTS
            .TOOL_CONFIGURATION_CONTROL}
          tabindex={settings.value.useAccessibleKeyboardSupport ? 0 : -1}
        >
          <i class="fas fa-cog"></i>
        </button>
      {/if}
    </li>
  {/each}
</ul>
